#include "opensim/services/region_baked_texture_runtime.hpp"
#include "opensim/services/scene_capabilities.hpp"
#include "opensim/server/http_route_registry.hpp"
#include "opensim/network/osd_value.hpp"
#include "opensim/services/flotsam_memory_cache.hpp"
#include <iostream>
#include <thread>
using namespace opensim;using namespace services;
namespace {
int checks=0;void check(bool value,const char* label){++checks;if(!value)throw std::runtime_error(label);}
struct Backend final:SceneCapabilityBackend{
 std::shared_ptr<server::RegistryCapabilityListener> registry;explicit Backend(std::shared_ptr<server::RegistryCapabilityListener> r):registry(std::move(r)){}
 std::string scene_name()const override{return "Script scene";}std::optional<std::string> region_name()const override{return "Scripts";}std::optional<std::string> external_host()const override{return "127.0.0.1";}std::shared_ptr<CapabilityRuntimeListener> listener()const override{return registry;}bool check_client(framework::Uuid,const network::HttpRequest&)override{return true;}
 void debug(const std::string&)override{}void warn(const std::string&)override{}void error(const std::string&)override{}void console(const std::string&)override{}void add_command(CapabilityCommand)override{}
};
void registration_profiles(){
 for(int mode=0;mode<3;++mode){auto registry=std::make_shared<server::RegistryCapabilityListener>(server::CapabilityListenerInfo{false,19009,0,{}});SceneCapabilities scene(std::make_shared<Backend>(registry));std::shared_ptr<framework::IAssetCache> cache;if(mode)cache=std::make_shared<FlotsamMemoryCache>(FlotsamMemoryCache::Options{true,true,600,120});auto url=mode==2?std::string("https://bakes.example/cap?x=1&y=2"):mode==1?std::string(" \t\xe2\x80\x83"):std::string("localhost");RegionBakedTextureRuntime runtime(scene.shared_events(),cache,url);auto circuit=std::make_shared<framework::AgentCircuitData>();circuit->agent_id=framework::Uuid::random();circuit->circuit_code=77;circuit->caps_path="bake-profile";scene.capabilities().set_agent_caps_seeds(circuit);scene.capabilities().create_caps(circuit->agent_id,77);auto caps=std::dynamic_pointer_cast<Caps>(scene.capabilities().get_caps_for_user(77));check(!caps->local_paths().contains("UploadBakedTexture"),"no invented local handler for missing cache, whitespace or external URL");auto external=caps->external_paths();check(mode==2?(external.contains("UploadBakedTexture")&&external.at("UploadBakedTexture")==url):!external.contains("UploadBakedTexture"),"source external URL and whitespace selection");runtime.stop();scene.shutdown();}
}
void run(bool expiry){
 auto registry=std::make_shared<server::RegistryCapabilityListener>(server::CapabilityListenerInfo{false,19007,0,{}});SceneCapabilities scene(std::make_shared<Backend>(registry));auto before=scene.events().on_register_caps.snapshot().size();auto agent=framework::Uuid::random();
 {RegionBakedTextureRuntime absent(scene.shared_events(),{},"localhost");check(scene.events().on_register_caps.snapshot().size()==before,"no cache means no source subscription");}
 auto cache=std::make_shared<FlotsamMemoryCache>(FlotsamMemoryCache::Options{true,true,600,120});RegionBakedTextureRuntime runtime(scene.shared_events(),cache,"localhost");check(scene.events().on_register_caps.snapshot().size()==before+1,"cache enables subscription");
 auto circuit=std::make_shared<framework::AgentCircuitData>();circuit->agent_id=agent;circuit->circuit_code=55;circuit->caps_path="bake-test";scene.capabilities().set_agent_caps_seeds(circuit);scene.capabilities().create_caps(agent,55);scene.capabilities().activate_caps(55);auto caps=std::dynamic_pointer_cast<Caps>(scene.capabilities().get_caps_for_user(55));check(bool(caps),"real caps created");auto paths=caps->local_paths();check(paths.contains("UploadBakedTexture"),"source name advertised");std::shared_ptr<server::CapabilitySimpleHandler> initial;check(registry->routes.try_simple(paths.at("UploadBakedTexture"),initial),"actual first-stage route");
 network::HttpRequest request;request.method="POST";request.remote_ip="127.0.0.1";request.body="malformed metadata accepted";
 auto create=[&](){auto response=initial->handle(request);check(response.status==200,"initial status");auto value=FetchInventory2Route::deserialize_xml_json(response.body);check(network::osd_string(value.get("state"))=="upload","initial upload state");auto url=network::osd_string(value.get("uploader"));check(url.ends_with("-BK"),"source bake suffix");auto path=url.substr(url.find('/',url.find("://")+3));std::shared_ptr<server::CapabilitySimpleHandler> upload;check(registry->routes.try_simple(path,upload),"binary route registered");check(runtime.pending_uploads()==1,"retains upload and timer");return std::pair(path,upload);};
 auto [path,upload]=create();network::HttpRequest binary;binary.method="POST";binary.remote_ip="127.0.0.1";binary.body=std::string("actual bake\0\xff",13);
 if(expiry){auto deadline=std::chrono::steady_clock::now()+std::chrono::seconds(35);while(runtime.pending_uploads()&&std::chrono::steady_clock::now()<deadline)std::this_thread::sleep_for(std::chrono::milliseconds(50));check(runtime.pending_uploads()==0,"real30-second timer retires upload");std::shared_ptr<server::CapabilitySimpleHandler> missing;check(!registry->routes.try_simple(path,missing),"expiry removes real route");check(upload->handle(binary).status==200,"source cached baked handle remains callable after timer disposal");}
 else{auto response=upload->handle(binary);check(response.status==200,"bake success");auto result=FetchInventory2Route::deserialize_xml_json(response.body);auto id=network::osd_uuid(result.get("new_asset"));auto stored=cache->get_cached(id.str());check(stored&&stored->type()==0&&stored->name()=="Baked Texture"&&stored->creator_id()==agent.str()&&stored->temporary()&&stored->local()&&stored->flags()==0&&std::string(stored->data->begin(),stored->data->end())==binary.body,"actual cache metadata and raw bytes");check(runtime.pending_uploads()==0,"one-shot released registry ownership");std::shared_ptr<server::CapabilitySimpleHandler> missing;check(!registry->routes.try_simple(path,missing),"one-shot actual route removed");auto again=upload->handle(binary);check(again.status==200,"source retained baked handler can repeat Stop/Dispose");auto another=create();auto bad=binary;bad.remote_ip="127.0.0.2";check(another.second->handle(bad).status==401&&runtime.pending_uploads()==0,"IP mismatch consumes uploader");auto abandoned=create();caps->deregister_handlers();std::shared_ptr<server::CapabilitySimpleHandler> retained;check(registry->routes.try_simple(abandoned.first,retained)&&runtime.pending_uploads()==1,"named cap disposal retains globally registered child");runtime.stop();runtime.stop();check(runtime.pending_uploads()==0&&!registry->routes.try_simple(abandoned.first,missing),"stop retires actual outstanding child");}
 runtime.stop();check(scene.events().on_register_caps.snapshot().size()==before,"stop unsubscribes");scene.shutdown();check(registry->routes.simple_keys().empty(),"named and child routes released");
}
}
int main(int argc,char**argv){try{registration_profiles();run(argc>1&&std::string_view(argv[1])=="--expiry");std::cout<<"PASS: "<<checks<<" baked registration/cache/lifetime checks\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
